package com.nbi.status.service;

import com.nbi.status.dto.TransferRequest;
import com.nbi.status.exception.*;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
public class TransferService {
    private final Map<String, BigDecimal> balances = new HashMap<>();

    public TransferService() {
        balances.put("SAV2001", new BigDecimal("1000000.00")); // Rajesh
        balances.put("CUR3001", new BigDecimal("250000.00"));  // Priya
    }

    public String transfer(TransferRequest r) {
        BigDecimal from = balances.get(r.from());
        if (from == null || !balances.containsKey(r.to()))
            throw new AccountNotFoundException("Account not found"); // → 404
        if (from.compareTo(r.amount()) < 0)
            throw new InsufficientFundsException("Insufficient funds"); // → 422
        balances.put(r.from(), from.subtract(r.amount()));
        balances.put(r.to(), balances.get(r.to()).add(r.amount()));
        return "TXF-" + UUID.randomUUID().toString().substring(0, 8);
    }
}
```

