package com.nbi.status.exception;

import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.bind.MethodArgumentNotValidException;

// Maps each exception to the correct HTTP status centrally.
@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(MethodArgumentNotValidException.class) // malformed/invalid input
    public ResponseEntity<String> badInput(MethodArgumentNotValidException e) {
        return ResponseEntity.badRequest().body("Invalid request"); // 400
    }

    @ExceptionHandler(AccountNotFoundException.class)
    public ResponseEntity<String> notFound(AccountNotFoundException e) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(e.getMessage()); // 404
    }

    @ExceptionHandler(InsufficientFundsException.class)
    public ResponseEntity<String> unprocessable(InsufficientFundsException e) {
        return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY).body(e.getMessage()); // 422
    }
}
